var data = $input.item.json.body || $input.item.json;
var evidenceRaw = $('Fetch Evidence').first().json;

var date = data.date || new Date().toISOString().split('T')[0];
var sources = (data.news_headlines || []).map(function(h) { return h.url; }).filter(Boolean);
var markets = (data.top_markets || []).map(function(m) { return m.symbol + ': $' + (m.price || 0).toLocaleString() + ' (' + (m.change_24h > 0 ? '+' : '') + (m.change_24h || 0).toFixed(2) + '% 24h)'; }).join(', ');
var trending = (data.trending_coins || []).map(function(c) { return c.name + ' (' + c.symbol + ')'; }).join(', ');
var reddit = (data.reddit_top_posts || []).slice(0,5).map(function(p) { return p.title; }).join('; ');
var headlines = (data.news_headlines || []).slice(0,8).map(function(h) { return h.title; }).join('; ');
var mcap = (data.market_summary && data.market_summary.total_market_cap_usd) ? '$' + (data.market_summary.total_market_cap_usd / 1e12).toFixed(2) + 'T' : 'N/A';
var btcDom = (data.market_summary && data.market_summary.btc_dominance) ? data.market_summary.btc_dominance.toFixed(1) + '%' : 'N/A';
var chg = (data.market_summary && data.market_summary.market_cap_change_24h_pct) ? data.market_summary.market_cap_change_24h_pct.toFixed(2) + '%' : 'N/A';

var afSignals = (evidenceRaw && evidenceRaw.alphaforge_signals) ? evidenceRaw.alphaforge_signals : [];
var marketTone = (evidenceRaw && evidenceRaw.market_tone) ? evidenceRaw.market_tone.toUpperCase() : 'UNKNOWN';
var riskFactors = (evidenceRaw && evidenceRaw.risk_factors) ? evidenceRaw.risk_factors : [];
var sourcesUsed = (evidenceRaw && evidenceRaw.sources_used) ? evidenceRaw.sources_used : [];

var sigLines = afSignals.slice(0, 6).map(function(s) {
  var confPct = Math.round(s.confidence * 100);
  var conf = (s.confluence && s.confluence !== 'null') ? ' | Confluence: ' + s.confluence : '';
  return s.symbol + ': ' + s.direction + ' | ' + confPct + '% confidence | Regime: ' + s.regime + conf;
}).join('\n');

var mktDataLines = '';
var afMarketData = (evidenceRaw && evidenceRaw.market_data) ? evidenceRaw.market_data : {};
Object.keys(afMarketData).forEach(function(sym) {
  var m = afMarketData[sym];
  if (m.price) {
    var priceStr = m.price > 100 ? '$' + m.price.toLocaleString('en-US', {maximumFractionDigits: 0}) : '$' + m.price.toFixed(4);
    var chgStr = m.change_24h != null ? ' (' + (m.change_24h > 0 ? '+' : '') + m.change_24h.toFixed(1) + '% 24h)' : '';
    mktDataLines += '\n' + sym + ': ' + priceStr + chgStr;
  }
});

var riskLines = riskFactors.slice(0, 3).join('; ');

var prompt = 'Date: ' + date + '.\n\n' +
  'AlphaForge Market Intelligence (Tier 1 - proprietary):\n' +
  'Overall market tone: ' + marketTone + '\n' +
  (sigLines ? 'Active signals:\n' + sigLines + '\n' : '') +
  'Risk factors: ' + (riskLines || 'Standard market risks apply') + '\n\n' +
  'Market Data (Tier 3):\n' +
  'Total market cap: ' + mcap + '. BTC dominance: ' + btcDom + '. 24h change: ' + chg + '.' +
  (mktDataLines ? mktDataLines : '') +
  (markets ? '\nTop assets: ' + markets : '') + '\n\n' +
  'Trending: ' + (trending || 'N/A') + '.\n' +
  'Reddit discussions: ' + (reddit || 'N/A') + '.\n' +
  'Headlines: ' + (headlines || 'N/A') + '.\n\n' +
  'Write the daily market brief for ' + date + '.';

var sys = 'You are Alpha Research, the voice of AlphaForgeAI — a research platform powered by a proprietary ML signal engine. You are a battle-tested crypto market analyst who was mining Bitcoin before Mt. Gox went down. You are a long-term Bitcoin Maximalist. BTC is the reserve asset. It is never going to zero.\n\n' +
  'Your audience: traders from beginners to experienced participants. Be accessible but substantive.\n\n' +
  'IMPORTANT content quality rules:\n' +
  '1. Use a SEARCH-INTENT title. Examples: Why Is Bitcoin Going Up Today?, Ethereum Technical Analysis: Is ETH Ready for a Breakout?, Bitcoin Price Signal: AlphaForge Turns Bullish. Never use generic titles like Daily Crypto Market Update.\n' +
  '2. State the overall market direction (Bullish/Bearish/Neutral) in the FIRST paragraph.\n' +
  '3. When AlphaForge signal data is provided, cite it explicitly: direction, confidence %, regime, confluence.\n' +
  '4. Include only supported claims. If data is unavailable, say so rather than inventing it.\n' +
  '5. Include risk factors before any directional conclusion.\n' +
  '6. End with a Sources & Confidence section as specified below.\n\n' +
  'Structure:\n' +
  '## [Search-intent title]\n' +
  '## Market Overview (Bullish/Bearish/Neutral with brief explanation)\n' +
  '## What Is Moving (BTC and ETH always; other assets when signal data or headlines justify it)\n' +
  '## Key Stories (macro, regulatory, on-chain when available)\n' +
  '## Risk Factors\n' +
  '## Closing Note\n\n' +
  'End every post with:\n' +
  'This post is for informational purposes only and does not constitute financial advice.\n\n' +
  'Then on its own line: TAGS: followed by 3-6 comma-separated lowercase kebab-case tags.\n\n' +
  'Then: SOURCES_JSON: followed by a single-line JSON object: {"sources": ["list of sources used"], "confidence_level": "High/Moderate/Low", "confidence_reason": "one sentence"}';

var body = JSON.stringify({ model: 'claude-sonnet-4-5', max_tokens: 2500, system: sys, messages: [{ role: 'user', content: prompt }] });
return [{ json: { date: date, sources: sources, claude_body: body, evidence: evidenceRaw || {} } }];

const claudeResp = $input.item.json;
let content = claudeResp.content?.[0]?.text || '';
const prev = $('Build Claude Prompt').item.json;
const date = prev.date;
const evidence = prev.evidence || {};

// Extract TAGS
const tagsMatch = content.match(/TAGS:\s*(.+)/i);
let tags = tagsMatch
  ? tagsMatch[1].split(',').map(t => t.trim().toLowerCase().replace(/[^a-z0-9-]/g, '')).filter(Boolean).slice(0, 6)
  : [];
if (tags.length === 0) tags = ['crypto', 'market', 'alphaforgeai'];

// Extract SOURCES_JSON
let sourcesData = {};
const sourcesMatch = content.match(/SOURCES_JSON:\s*(\{[^}]+\})/);
if (sourcesMatch) { try { sourcesData = JSON.parse(sourcesMatch[1]); } catch(e) {} }

// Strip TAGS and SOURCES_JSON from displayed content
let cleanContent = content
  .replace(/\nTAGS:\s*.+/i, '')
  .replace(/\nSOURCES_JSON:\s*\{[^}]+\}/, '')
  .trim();

// Extract title from first H1/H2
const titleMatch = cleanContent.match(/^#{1,2}\s+(.+)$/m);
const title = titleMatch ? titleMatch[1].trim() : ('AlphaForge Daily Brief — ' + date);

// Build slug
const slug = title.toLowerCase().replace(/[^\w\s-]/g, '').replace(/[\s_]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) + '-' + date;

// Summary from first substantial paragraph
const paraMatch = cleanContent.replace(/^#{1,3}.+$/m, '').match(/([^\n]{80,})/);
const summary = paraMatch ? paraMatch[1].slice(0, 200) : cleanContent.slice(0, 200);

// Assets from signals
const assetSymbols = (evidence.alphaforge_signals || []).slice(0, 4).map(s => s.symbol);

// Build Sources & Confidence section
const sourcesList = (sourcesData.sources || evidence.sources_used || ['AlphaForge ML signal engine']).join(', ');
const confLevel = sourcesData.confidence_level || 'Moderate';
const confReason = sourcesData.confidence_reason || 'Based on AlphaForge signal data and available market context.';
const sourcesSection = '\n\n## Sources & Confidence\n\nData used: ' + sourcesList + '\n\nConfidence level: ' + confLevel + '\n\nReason: ' + confReason;
const fullContent = cleanContent + sourcesSection;

// Generate X post variants from evidence
const signals = evidence.alphaforge_signals || [];
const directional = signals.filter(s => s.direction === 'LONG' || s.direction === 'SHORT');
directional.sort((a, b) => b.confidence - a.confidence);
const topSig = directional[0];

const assetNames = { BTC: 'Bitcoin', ETH: 'Ethereum', SOL: 'Solana', INJ: 'Injective', AVAX: 'Avalanche', DOT: 'Polkadot', XRP: 'XRP', NEAR: 'NEAR', UNI: 'Uniswap', ARB: 'Arbitrum', OP: 'Optimism', SUI: 'Sui', APT: 'Aptos' };

let xPosts = { signal_card: '', hook: '', risk_aware: '' };
if (topSig) {
  const assetName = assetNames[topSig.symbol] || topSig.symbol;
  const confPct = Math.round(topSig.confidence * 100);
  const dir = topSig.direction === 'LONG' ? 'BUY' : 'SELL';
  const riskLine = (evidence.risk_factors || ['Monitor for regime change.'])[0].slice(0, 90);
  const hashtag = ['BTC','ETH','SOL'].includes(topSig.symbol) ? ' #' + topSig.symbol : '';
  const confLine = topSig.confluence && topSig.confluence !== 'null' ? '\nConfluence: ' + topSig.confluence : '';

  xPosts.signal_card = assetName + ' Signal Update\n\nAlphaForge: ' + dir + '\nConfidence: ' + confPct + '%\nRegime: ' + topSig.regime + confLine + '\n\n' + topSig.thesis.slice(0, 100) + (topSig.thesis.length > 100 ? '...' : '') + '\n\nRisk: ' + riskLine + '\n\n$' + topSig.symbol + hashtag;
  xPosts.hook = 'Most traders are watching ' + assetName + ' price.\n\nAlphaForge is watching regime, volume, and model conviction.\n\nCurrent signal:\n' + dir + '\nConfidence: ' + confPct + '%\nRegime: ' + topSig.regime + '\n\n$' + topSig.symbol;
  xPosts.risk_aware = assetName + ' momentum is ' + (topSig.direction === 'LONG' ? 'improving' : 'weakening') + ', but this is not a blind ' + (topSig.direction === 'LONG' ? 'long' : 'short') + '.\n\nAlphaForge signal:\n' + dir + '\nConfidence: ' + confPct + '%\n\nMain risk:\n' + riskLine + '\n\n' + (topSig.direction === 'LONG' ? 'Bullish' : 'Bearish') + ' setup — but risk still matters.\n\n$' + topSig.symbol + hashtag;
} else {
  const tone = (evidence.market_tone || 'neutral').toUpperCase();
  xPosts.signal_card = 'AlphaForge Market Read\n\nTone: ' + tone + '\n\nFull analysis: alphaforgeai.io/blog/' + slug + '\n\n#AlphaForgeAI';
  xPosts.hook = 'The crypto market is giving a ' + tone.toLowerCase() + ' read today.\n\nAlphaForge breakdown: alphaforgeai.io/blog/' + slug + '\n\n$BTC $ETH';
  xPosts.risk_aware = xPosts.hook;
}

function trimTweet(t) { return t.length <= 280 ? t : t.slice(0, 277) + '...'; }
xPosts.signal_card = trimTweet(xPosts.signal_card);
xPosts.hook = trimTweet(xPosts.hook);
xPosts.risk_aware = trimTweet(xPosts.risk_aware);

const contentScore = (signals.length > 0) ? 85 : 60;

return [{
  json: {
    schema_version: 1,
    posts: [{
      title, slug,
      published_at: new Date().toISOString(),
      summary,
      content: fullContent,
      sources: prev.sources || [],
      assets: assetSymbols,
      tags,
      author: 'Alpha Research',
      x_posts: xPosts,
      content_score: contentScore,
      evidence: {
        market_tone: evidence.market_tone || 'unknown',
        signal_count: signals.length,
        top_signals: directional.slice(0, 3).map(s => ({ symbol: s.symbol, direction: s.direction, confidence: s.confidence, regime: s.regime })),
        sources_used: evidence.sources_used || [],
        risk_factors: evidence.risk_factors || [],
      },
    }],
  }
}];
